package cl.bolsillo.app;
import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.drawable.Drawable;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Package queries and icon decoding never occupy the UI thread; only visible rows are built. */
final class AppPicker {
 static final ExecutorService IO=Executors.newSingleThreadExecutor();
 static final class Item {final String pkg,label,kind;final boolean suggested;Drawable icon;Item(String pkg,String label){this.pkg=pkg;this.label=label;kind=PaymentCards.kind(label,pkg);suggested=PaymentCards.recommended(label,pkg);}}
 static void show(MainActivity a)throws Exception{
  JSONArray current=Detection.sources(a);Set<String> selected=new HashSet<>();for(int i=0;i<current.length();i++)selected.add(current.getJSONObject(i).getString("package"));
  LinearLayout box=NativeSettings.panel(a,"Apps de tus compras");box.addView(Modern.text(a,"Elige tus bancos, Wallet, Onepay y Gmail.",14,Glass.subtle(a),false));Dialog dialog=new Dialog(a);Glass.privacy(dialog.getWindow(),a);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);EditText search=NativeSettings.input(a,box,"Buscar app","");TextView status=Modern.text(a,"Buscando apps…",13,Glass.subtle(a),false);box.addView(status);ListView list=new ListView(a);list.setDivider(null);list.setVerticalScrollBarEnabled(false);list.setCacheColorHint(android.graphics.Color.TRANSPARENT);box.addView(list,new LinearLayout.LayoutParams(-1,0,1));List<Item> all=new ArrayList<>(),visible=new ArrayList<>();
  BaseAdapter adapter=new BaseAdapter(){public int getCount(){return visible.size();}public Object getItem(int n){return visible.get(n);}public long getItemId(int n){return n;}public View getView(int n,View recycled,ViewGroup parent){Item item=visible.get(n);CheckBox row=recycled instanceof CheckBox?(CheckBox)recycled:new CheckBox(a);if(recycled==null){Controls.style(row);row.setTypeface(Glass.font(a,400));row.setTextColor(Glass.ink(a));row.setMinHeight(a.dp(64));row.setPadding(a.dp(4),a.dp(7),a.dp(6),a.dp(7));row.setCompoundDrawablePadding(a.dp(10));row.setMaxLines(2);row.setEllipsize(android.text.TextUtils.TruncateAt.END);}row.setText(item.label+(item.suggested?" · Sugerida":""));row.setOnCheckedChangeListener(null);row.setChecked(selected.contains(item.pkg));Drawable icon=item.icon;if(icon!=null)icon.setBounds(0,0,a.dp(28),a.dp(28));row.setCompoundDrawablesRelative(null,null,icon,null);row.setOnCheckedChangeListener((button,checked)->{if(checked)selected.add(item.pkg);else selected.remove(item.pkg);});return row;}};list.setAdapter(adapter);
  Runnable filter=()->{String query=BankNotificationParser.normalize(search.getText().toString());visible.clear();for(Item item:all)if(BankNotificationParser.normalize(item.label).contains(query))visible.add(item);adapter.notifyDataSetChanged();};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){filter.run();}public void afterTextChanged(Editable e){}});
  Button suggested=Glass.button(a,"Marcar apps sugeridas");box.addView(suggested);suggested.setEnabled(false);suggested.setOnClickListener(v->{for(Item item:all)if(item.suggested)selected.add(item.pkg);adapter.notifyDataSetChanged();});Button save=Glass.button(a,"Guardar selección");box.addView(save);save.setEnabled(false);save.setOnClickListener(v->a.attempt(()->{JSONArray next=new JSONArray();for(Item item:all)if(selected.contains(item.pkg))next.put(new JSONObject().put("package",item.pkg).put("label",item.label).put("kind",item.kind).put("account","").put("enabled",true));NativeStore.settings(a).edit().putString("sources",PaymentCards.mergeSelection(current,next).toString()).apply();dialog.dismiss();a.render(false);}));Button cancel=Glass.button(a,"Cancelar");box.addView(cancel);cancel.setOnClickListener(v->dialog.dismiss());dialog.setContentView(box);dialog.show();Glass.window(dialog,a);dialog.getWindow().setLayout(Math.min(a.dp(460),a.getResources().getDisplayMetrics().widthPixels-a.dp(16)),a.getResources().getDisplayMetrics().heightPixels-a.dp(100));Context app=a.getApplicationContext();
  IO.execute(()->{try{PackageManager pm=app.getPackageManager();LinkedHashMap<String,Item> found=new LinkedHashMap<>();for(int i=0;i<current.length();i++){JSONObject old=current.getJSONObject(i);found.put(old.getString("package"),new Item(old.getString("package"),old.optString("label")));}List<ResolveInfo> installed=pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0);for(ResolveInfo result:installed){String pkg=result.activityInfo.packageName;if(pkg.equals(app.getPackageName())||found.containsKey(pkg))continue;found.put(pkg,new Item(pkg,result.loadLabel(pm).toString()));}List<Item> items=new ArrayList<>(found.values());for(Item item:items)try{item.icon=pm.getApplicationIcon(item.pkg);}catch(Exception ignored){}items.sort((x,y)->x.suggested==y.suggested?x.label.compareToIgnoreCase(y.label):x.suggested?-1:1);a.runOnUiThread(()->{if(!dialog.isShowing()||a.isDestroyed())return;all.addAll(items);status.setVisibility(View.GONE);suggested.setEnabled(true);save.setEnabled(true);filter.run();});}catch(Exception error){a.runOnUiThread(()->{if(dialog.isShowing())status.setText("No se pudieron cargar las apps. Cierra y vuelve a intentar.");});}});
 }
}
